<?php require_once "../config/database.php";require_once "../includes/functions.php";require_admin();$rows=$pdo->query("SELECT name,email,phone,created_at FROM users WHERE role='customer' ORDER BY created_at DESC")->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Customers</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><?php include "../includes/navbar.php";?><main class="container page"><span class="eyebrow">ADMIN</span><h1>Customers.</h1><div class="table-wrap"><table><tr><th>Name</th><th>Email</th><th>Phone</th><th>Joined</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r["name"])?></td><td><?=e($r["email"])?></td><td><?=e($r["phone"])?></td><td><?=e($r["created_at"])?></td></tr><?php endforeach;?></table></div></main></body></html>